import{_ as u,C as i,o as r,c as p,j as t,a,b as d,w as s,E as o,a8 as l,a9 as h}from"./chunks/framework.BOiBTRPC.js";const D=JSON.parse('{"title":"DataOps & Orchestration","description":"Run pipelines in production like a grown-up — orchestrators, idempotent backfills, quality gates, contracts, and incident response.","frontmatter":{"title":"DataOps & Orchestration","description":"Run pipelines in production like a grown-up — orchestrators, idempotent backfills, quality gates, contracts, and incident response."},"headers":[],"relativePath":"dataops/index.md","filePath":"dataops/index.md"}'),m={name:"dataops/index.md"};function g(y,e,b,f,w,k){const n=i("Mermaid"),c=i("QuizCard");return r(),p("div",null,[e[2]||(e[2]=t("h1",{id:"dataops-orchestration",tabindex:"-1"},[a("DataOps & Orchestration "),t("a",{class:"header-anchor",href:"#dataops-orchestration","aria-label":'Permalink to "DataOps & Orchestration"'},"​")],-1)),e[3]||(e[3]=t("blockquote",null,[t("p",null,[t("strong",null,"Why it matters"),a(" — A pipeline that works on your laptop is a script; a pipeline that survives a 3am partial outage, backfills three months without double-loading, and tells downstream consumers "),t("em",null,"before"),a(" they notice stale data is a system. This track is the difference.")])],-1)),e[4]||(e[4]=t("p",null,[t("strong",null,"Who this is for:"),a(" data engineers who can already build pipelines and want to run them reliably in production — and pass the senior-interview questions about orchestration trade-offs and data quality frameworks.")],-1)),(r(),d(l,null,{default:s(()=>[o(n,{id:"mermaid-11",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Orchestration%22%5D%20--%3E%20B%5B%22Scheduling%20and%20dependencies%22%5D%0A%20%20A%20--%3E%20C%5B%22Retries%2C%20idempotency%2C%20backfills%22%5D%0A%20%20A%20--%3E%20D%5B%22Airflow%20vs%20Dagster%20vs%20Prefect%22%5D%0A%20%20E%5B%22Quality%20and%20Contracts%22%5D%20--%3E%20F%5B%22Quality%20dimensions%20and%20tests%22%5D%0A%20%20E%20--%3E%20G%5B%22Observability%20and%20freshness%20SLOs%22%5D%0A%20%20E%20--%3E%20H%5B%22Data%20contracts%20and%20governance-lite%22%5D%0A%20%20C%20-.-%3E%7C%22bad%20runs%20become%20incidents%22%7C%20E%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=h('<h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><p><strong><a href="/Data-Knowledge/dataops/orchestration.html">Orchestration</a></strong> — Why schedulers earn their keep: dependency graphs, retries, observability, and backfills that don&#39;t double-load. Airflow&#39;s architecture and mental model (DAGs, operators, sensors, <code>data_interval</code>, catchup), deferrable operators, dynamic DAGs, and the anti-patterns that get you paged. Then the honest comparison: when Dagster&#39;s asset-first model beats Airflow&#39;s task graphs, where Prefect fits, how dbt slots in, and how to ship DAG changes through CI/CD without breaking prod.</p><p><strong><a href="/Data-Knowledge/dataops/quality.html">Transformation, Quality &amp; Contracts</a></strong> — Data quality as an engineering discipline, not a vibe. The six quality dimensions and where each gets enforced; dbt tests vs Great Expectations vs anomaly monitoring; lineage and freshness SLOs; data contracts that put enforcement on the producer side; incident management for data; and governance-lite — catalog, ownership, PII tiers — the 20% that gets you 80% of compliance.</p><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>The ideas in this track that matter most in real systems and interviews:</p><ul><li><strong>Idempotency is the whole game.</strong> A task that can rerun and re-produce the same partition output unlocks retries, backfills, and painless incident recovery.</li><li><strong>Data interval ≠ run time.</strong> Airflow schedules the <em>end</em> of an interval, not the start. Misreading this is the #1 source of &quot;why is my DAG a day behind&quot; bugs.</li><li><strong>Sensors are polling; defer them or pay for the slot.</strong> Deferrable operators free worker slots while waiting on external state.</li><li><strong>Assets over tasks.</strong> Declaring <em>what should exist</em> (Dagster) gives lineage, backfills, and freshness for free where tasks only give you logs.</li><li><strong>Quality gates belong between layers, not at the end.</strong> Quarantine bronze, enforce on silver, publish gold — catching bad data downstream of a dashboard is a postmortem, not a check.</li><li><strong>A contract is a schema plus an SLA plus an owner.</strong> Enforcement belongs at the producer; consumer-side checks are the safety net.</li></ul><h2 id="dataops-is-an-undercurrent-not-a-stage" tabindex="-1">DataOps is an undercurrent, not a stage <a class="header-anchor" href="#dataops-is-an-undercurrent-not-a-stage" aria-label="Permalink to &quot;DataOps is an undercurrent, not a stage&quot;">​</a></h2><p>The data engineering lifecycle — generate, ingest, store, transform, serve — reads like a pipeline, but the disciplines in this track aren&#39;t a box in that pipeline. Reis &amp; Housley call them <em>undercurrents</em>: security, data management, DataOps, data architecture, orchestration, and software engineering run underneath <em>every</em> stage simultaneously. A quality check isn&#39;t a step after transform; it&#39;s a property each stage must carry.</p>',8)),(r(),d(l,null,{default:s(()=>[o(n,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20L%5B%22Data%20engineering%20lifecycle%22%5D%0A%20%20%20%20A%5B%22Generate%22%5D%20--%3E%20B%5B%22Ingest%22%5D%20--%3E%20C%5B%22Store%22%5D%20--%3E%20D%5B%22Transform%22%5D%20--%3E%20E%5B%22Serve%22%5D%0A%20%20end%0A%20%20U1%5B%22Orchestration%22%5D%20-.-%3E%20A%0A%20%20U1%20-.-%3E%20E%0A%20%20U2%5B%22Quality%20and%20security%22%5D%20-.-%3E%20A%0A%20%20U2%20-.-%3E%20E%0A%20%20U3%5B%22Ops%3A%20automation%2C%20observability%2C%20incident%20response%22%5D%20-.-%3E%20A%0A%20%20U3%20-.-%3E%20E%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=h('<p>The book&#39;s three pillars of DataOps map cleanly onto this track:</p><table tabindex="0"><thead><tr><th>Pillar</th><th>What it is</th><th>Where you see it here</th></tr></thead><tbody><tr><td><strong>Automation</strong></td><td>Version control, CI/CD, config-as-code for pipelines — so a bad DAG can&#39;t be hand-deployed at 5pm on Friday</td><td>Orchestration: DAG deploy pipelines, <code>dbt build</code> gating</td></tr><tr><td><strong>Observability &amp; monitoring</strong></td><td>Bad data is a silent killer — it sits in reports for months while executives decide on it. Watch freshness, volume, schema, and drift</td><td>Quality: freshness SLOs, lineage, anomaly monitoring</td></tr><tr><td><strong>Incident response</strong></td><td>Systems <em>will</em> break. The job is root-causing fast and telling consumers before they notice</td><td>Blameless postmortems, proactive comms, backfill runbooks</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight — the order matters</p><p>Retrofitting DataOps onto an existing mess? The book&#39;s sequence: <strong>observability first</strong> (you can&#39;t fix what you can&#39;t see), then <strong>automation</strong> (stop hand-deploying), then <strong>incident response</strong> (formalize the response loop). Reversing it — writing runbooks for failures you can&#39;t detect — is how teams end up with wikis nobody reads.</p></div><h2 id="what-dataops-maturity-actually-looks-like" tabindex="-1">What DataOps maturity actually looks like <a class="header-anchor" href="#what-dataops-maturity-actually-looks-like" aria-label="Permalink to &quot;What DataOps maturity actually looks like&quot;">​</a></h2><p>The book traces a familiar trajectory: cron jobs on a box → jobs collide and nobody notices until analysts complain → an orchestrator arrives → a bad hand-deployed DAG takes down the webserver → deployments get automated. Where you are on that ladder predicts your failure modes:</p><table tabindex="0"><thead><tr><th>Org size</th><th>Typical setup</th><th>What breaks</th><th>The maturity move</th></tr></thead><tbody><tr><td><strong>~1 data person</strong></td><td>Cron + scripts, one-off reports, generalist wears all hats</td><td>Silent failures, nobody notices stale data for weeks; the laptop <em>is</em> prod</td><td>Just get observability — a stale-table alert beats a perfect orchestrator you don&#39;t have time to run. Avoid undifferentiated heavy lifting; buy managed, don&#39;t self-host Airflow</td></tr><tr><td><strong>~5 data people</strong></td><td>Orchestrator adopted, dbt in place, still hand-deploying DAGs</td><td>Job collisions, deploys breaking prod, splinter teams forming when trust erodes</td><td>Automate deployment: CI-tested DAGs, <code>dbt build</code> gates between layers, named ownership per domain</td></tr><tr><td><strong>~50 data people</strong></td><td>Platform team, federated domains, contracts between teams</td><td>Cross-team breakage at scale; one domain&#39;s schema change silently corrupts another&#39;s model</td><td>Contracts + SLOs as organizational APIs: producers enforce schemas, freshness SLOs are negotiated, incident response spans teams</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Trust is the real SLO</p><p>The book&#39;s warning: when stakeholders find stale or wrong data <em>before</em> the data team does, they don&#39;t just lose trust — they spin up shadow systems and splinter teams, and now you have inconsistent numbers <em>and</em> more systems to support. Telling consumers &quot;we know, we&#39;re on it&quot; before they notice is worth more than most tests.</p></div><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><p>Work this track front to back: <strong>orchestration</strong> gives you the machinery that runs the lifecycle, <strong>dbt</strong> gives you the transform layer where most gates live, and <strong>quality &amp; contracts</strong> gives you what to enforce and how to respond when it fires. Skipping to quality without orchestration is writing checks your scheduler can&#39;t cash.</p><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',10)),o(c,{questions:[{q:"A team wants to add DataOps practices to a legacy pipeline estate they barely understand. What should they build first?",options:["Observability and monitoring","A formal incident-response runbook","Automated CI/CD for DAG deploys","Data contracts between producers and consumers"],correct:0,explain:"Observability first — you cannot automate or respond to failures you cannot see. Automation second, incident response third."},{q:"Under Reis & Housley’s undercurrent model, where do orchestration and data quality sit in the lifecycle?",options:["As the final stage after serving data","As undercurrents beneath every stage from generation to serving","Only in the transform stage","As a separate lifecycle that runs weekly"],correct:1,explain:"They are undercurrents — cross-cutting disciplines that apply at every stage, not a step you pass through once."},{q:"Stakeholders report a dashboard has been stale for days before the data team noticed. Beyond the missed SLA, what is the bigger risk the book warns about?",options:["The warehouse bill increases","The orchestrator will backfill automatically","The dashboard will be deprecated","Stakeholders lose trust and spin up shadow teams and splinter systems"],correct:3,explain:"Undetected bad data erodes trust; teams respond by building their own pipelines, multiplying inconsistency and systems to support."}]}),e[7]||(e[7]=t("h2",{id:"further-reading",tabindex:"-1"},[a("Further reading "),t("a",{class:"header-anchor",href:"#further-reading","aria-label":'Permalink to "Further reading"'},"​")],-1)),e[8]||(e[8]=t("ul",null,[t("li",null,[t("strong",null,"Fundamentals of Data Engineering"),a(" — Joe Reis & Matt Housley (2022), "),t("a",{href:"https://www.oreilly.com/library/view/fundamentals-of-data/9781098108298/",target:"_blank",rel:"noreferrer"},"O'Reilly"),a(" — Chapters 1–2 on the lifecycle, undercurrents, and data maturity.")])],-1))])}const v=u(m,[["render",g]]);export{D as __pageData,v as default};
